// function — without running it once eagerly, a dark-mode OS loads with "system" marked
// selected but the light scheme still applied, until the user clicks another option and back.
const applyAppearance = (appearance: "system" | "light" | "dark"): void => {
  const selectedMode =
    appearance === "system"
      ? window.matchMedia("(prefers-color-scheme: dark)").matches
        ? "dark"
        : "light"
      : appearance;
  document.body.dataset.appearanceMode = appearance;
  document.documentElement.style.colorScheme = selectedMode;
  document.documentElement.dataset.pantokenScheme = selectedMode;
  if (typeof applyChromeTheme === "function") {
    applyChromeTheme(selectedTheme ?? "rebrand", selectedMode as "light" | "dark");
  }
  for (const candidate of themePanel.querySelectorAll<HTMLButtonElement>("[data-appearance]")) {
    candidate.classList.toggle("is-selected", candidate.dataset.appearance === appearance);
  }
};
for (const [appearance, label, icon] of [
  ["system", "System", SunMedium],
  ["light", "Light", SunMedium],
  ["dark", "Dark", MoonStar],
] as const) {
  const option = document.createElement("button");
  option.type = "button";
  option.className = "canvas-rce-shell__option";
  option.dataset.appearance = appearance;
  const text = document.createElement("span");
  text.textContent = label;
  const mark = document.createElement("span");
  mark.className = "canvas-rce-shell__mark";
  mark.append(createShellIcon(icon));
  option.append(text, mark);
  if (appearance === "system") option.classList.add("is-selected");
  option.addEventListener("click", () => {
    applyAppearance(appearance);
    themeMenu.removeAttribute("open");
  });
  appearanceGroup.append(option);
}

